package org.apache.commons.lang3.text.translate;

import java.io.*;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import java.util.Locale;
import org.apache.commons.lang3.text.translate.CharSequenceTranslator;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;

public class CharSequenceTranslator_with_TriageGen1Test {

    /**
     * Mock implementation of CharSequenceTranslator to verify aggregation logic.
     */
    private static class MockTranslator extends CharSequenceTranslator {
        private final String replacement;

        MockTranslator(String replacement) {
            this.replacement = replacement;
        }

        @Override
        public int translate(CharSequence input, int index, StringWriter out) throws IOException {
            out.write(replacement);
            return replacement.length();
        }

        @Override
        public int translate(CharSequence input, int index, java.io.Writer out) throws IOException {
            out.write(replacement);
            return replacement.length();
        }
    }

    @Test
    public void testWith_SingleTranslator() throws IOException {
        // Arrange
        CharSequenceTranslator base = new MockTranslator("base");
        CharSequenceTranslator extra = new MockTranslator("extra");

        // Act
        CharSequenceTranslator result = base.with(extra);

        // Assert
        assertNotNull(result);
        StringWriter sw = new StringWriter();
        // The 'with' method prepends 'this' to the new array. 
        // AggregateTranslator applies translators in order.
        // Expected: "baseextra"
        result.translate("any", sw);
        assertEquals("baseextra", sw.toString());
    }

    @Test
    public void testWith_MultipleTranslators() throws IOException {
        // Arrange
        CharSequenceTranslator base = new MockTranslator("A");
        CharSequenceTranslator t1 = new MockTranslator("B");
        CharSequenceTranslator t2 = new MockTranslator("C");

        // Act
        CharSequenceTranslator result = base.with(t1, t2);

        // Assert
        StringWriter sw = new StringWriter();
        result.translate("any", sw);
        assertEquals("ABC", sw.toString());
    }

    @Test
    public void testWith_NoTranslators() throws IOException {
        // Arrange
        CharSequenceTranslator base = new MockTranslator("base");

        // Act
        // Passing empty varargs
        CharSequenceTranslator result = base.with();

        // Assert
        StringWriter sw = new StringWriter();
        result.translate("any", sw);
        // Result should contain only the base translator
        assertEquals("base", sw.toString());
    }

    @Test
    public void testWith_NullParameter() throws IOException {
        // Arrange
        CharSequenceTranslator base = new MockTranslator("base");

        // Act & Assert
        // Since the method uses translators.length, passing null directly to varargs 
        // will cause a NullPointerException when accessing length.
        try {
            base.with(null);
        } catch (NullPointerException e) {
            // Expected behavior for null array input in this implementation
        }
    }

    @Test
    public void testWith_VerifiesOrder() throws IOException {
        // Arrange
        // Use translators that modify state or specific characters to ensure order
        // Base: replaces 'a' with '1'
        // Extra: replaces 'b' with '2'
        CharSequenceTranslator base = new CharSequenceTranslator() {
            @Override
            public int translate(CharSequence input, int index, java.io.Writer out) throws IOException {
                out.write("1");
                return 1;
            }
            @Override
            public int translate(CharSequence input, int index, StringWriter out) throws IOException {
                out.write("1");
                return 1;
            }
        };

        CharSequenceTranslator extra = new CharSequenceTranslator() {
            @Override
            public int translate(CharSequence input, int index, java.io.Writer out) throws IOException {
                out.write("2");
                return 1;
            }
            @Override
            public int translate(CharSequence input, int index, StringWriter out) throws IOException {
                out.write("2");
                return 1;
            }
        };

        // Act
        CharSequenceTranslator result = base.with(extra);

        // Assert
        // AggregateTranslator typically iterates through the array.
        // The array is [base, extra].
        // We call translate on a string that triggers both (conceptually).
        // However, since we are mocking the core translate method, we just check the sequence of writes.
        StringWriter sw = new StringWriter();
        // We simulate a call that would trigger both if the AggregateTranslator logic is correct.
        // Note: AggregateTranslator's translate method usually iterates through translators.
        result.translate("test", sw);

        // Based on the 'with' implementation: newArray[0] = this; newArray[1] = extra;
        // The AggregateTranslator will execute base then extra.
        assertEquals("12", sw.toString());
    }
}
